import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

type Step = { text: string };

export type HowItWorksProps = {
  title: string;
  steps: Step[];
};

export default function HowItWorks({ title, steps }: HowItWorksProps) {
  const reduceMotion = useReducedMotion();

  return (
    <LazyMotion features={domAnimation}>
      <section className="bg-background font-sans text-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>

          <ol className="mt-10 grid gap-10 md:grid-cols-3 md:gap-8">
            {steps.map((step, i) => (
              <m.li
                key={step.text}
                initial={reduceMotion ? false : { opacity: 0, y: 16 }}
                whileInView={reduceMotion ? undefined : { opacity: 1, y: 0 }}
                viewport={{ once: true, margin: "-80px" }}
                transition={{ duration: 0.5, delay: i * 0.12, ease: "easeOut" }}
                className="min-w-0 border-t-2 border-primary pt-5"
              >
                <div className="flex items-baseline gap-3">
                  <span
                    aria-hidden="true"
                    className="shrink-0 font-display text-h3 font-bold text-primary tabular-nums"
                  >
                    {i + 1}
                  </span>
                  <p className="min-w-0 text-body text-pretty text-muted-foreground wrap-break-word">
                    {step.text}
                  </p>
                </div>
              </m.li>
            ))}
          </ol>
        </div>
      </section>
    </LazyMotion>
  );
}

