          </div>
          <m.div {...enter(1)} className="min-w-0 lg:col-span-6">
            <img
              src={image.src}
              srcSet={srcSetOf(image.src)}
              sizes="(min-width: 1024px) 50vw, 100vw"
              alt={image.alt}
              fetchPriority="high"
              className="aspect-4/3 w-full rounded-lg bg-muted object-cover lg:aspect-4/5"
            />
          </m.div>
        </div>
      </section>
    </LazyMotion>
  );
}
