import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

type Step = { text: string };

export type HowItWorksProps = {
  title: string;
  steps: Step[];
};

export default function HowItWorks({ title, steps }: HowItWorksProps) {
  const reduceMotion = useReducedMotion();

  return (
    <LazyMotion features={domAnimation}>
      <section className="bg-background font-sans text-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <div className="grid gap-10 md:grid-cols-12 md:gap-8">
            <div className="min-w-0 md:col-span-4">
              <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>
            </div>

            <ol className="min-w-0 md:col-span-8">
              {steps.map((step, index) => (
                <m.li
                  key={step.text}
                  initial={reduceMotion ? false : { y: 16 }}
                  whileInView={reduceMotion ? undefined : { opacity: 1, y: 0 }}
                  viewport={{ once: true, amount: 0.4 }}
                  transition={{ duration: 0.5, delay: index * 0.12, ease: "easeOut" }}
                  className="flex items-baseline gap-6 border-t border-border py-6 first:border-t-0 first:pt-0 last:pb-0 md:gap-8"
                >
                  <span
                    aria-hidden="true"
                    className="shrink-0 font-display text-hero font-bold leading-none text-primary tabular-nums"
                  >
                    {index + 1}
                  </span>
                  <p className="min-w-0 text-lead text-pretty text-foreground wrap-break-word">
                    {step.text}
                  </p>
                </m.li>
              ))}
            </ol>
          </div>
        </div>
      </section>
    </LazyMotion>
  );
}
